eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   pageMetadata: () => (/* binding */ pageMetadata)\n/* harmony export */ });\n/* harmony import */ var _siteData__WEBPACK_IMPORTED_MODULE_0__ = __webpack_require__(/*! ./siteData */ \"(rsc)/./lib/siteData.js\");\n\nfunction pageMetadata(title, description, path = \"/\", imagePath) {\n    const url = `${_siteData__WEBPACK_IMPORTED_MODULE_0__.seo.baseUrl}${path}`;\n    const image = imagePath ? `${_siteData__WEBPACK_IMPORTED_MODULE_0__.seo.baseUrl}${imagePath}` : undefined;\n    return {\n        title,\n        description,\n        alternates: {\n            canonical: url\n        },\n        openGraph: {\n            title,\n            description,\n            url,\n            siteName: _siteData__WEBPACK_IMPORTED_MODULE_0__.seo.siteName,\n            type: \"website\",\n            images: image ? [\n                {\n                    url: image\n                }\n            ] : undefined\n        },\n        twitter: {\n            card: \"summary_large_image\",\n            title,\n            description,\n            images: image ? [\n                image\n            ] : undefined\n        }\n    };\n}\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(rsc)/./lib/metadata.js\n");

